/**
 * TypeScript schema for `data/catalog.json` (generated by `scripts/build_catalog.py`).
 * Single source of truth for the Awesome Blender web application.
 */

export type Locale = "en" | "zh";

export interface LocalizedText {
    en: string;
    zh: string;
}

export type EntryKind = "item" | "collection" | "social-handle" | "quick-link";

export type MediaType = "video" | "playlist" | "channel" | "doc" | "course";

export type LicenseCode = "gpl" | "mit" | "zero" | "cc" | "by" | "nc";

export type PlatformTag =
    | "extensions"
    | "github"
    | "gitlab"
    | "bitbucket"
    | "open-source"
    | "superhive"
    | "gumroad"
    | "youtube"
    | "blender-docs";

export type SecondaryLinkType =
    | "repo"
    | "market"
    | "license"
    | "docs"
    | "website"
    | "thread"
    | "info"
    | "companion"
    | "collection-item"
    | "other";

export interface SecondaryLink {
    label: LocalizedText;
    url: string;
    type: SecondaryLinkType;
}

export interface CatalogEntry {
    id: string;
    line: number;
    kind: EntryKind;
    sectionId: string;
    categoryId: string;
    subgroupId: string | null;
    subgroup: LocalizedText | null;
    parentId?: string;
    title: LocalizedText;
    url: string | null;
    description: LocalizedText;
    descriptionMd: LocalizedText;
    secondaryLinks: SecondaryLink[];
    allUrls: string[];
    isPaid: boolean;
    isFree: boolean;
    licenses: LicenseCode[];
    mediaType: MediaType | null;
    platforms: PlatformTag[];
    githubRepo: string | null;
    blenderExtensionId: string | null;
}

export interface CatalogSubgroup {
    id: string;
    line: number;
    title: LocalizedText;
    url: string | null;
    mediaType: MediaType | null;
}

export interface CatalogCategory {
    id: string;
    slug: string;
    sectionId: string;
    line: number;
    emoji: string | null;
    title: LocalizedText;
    url: string | null;
    note: LocalizedText | null;
    subgroups: CatalogSubgroup[];
    entries: CatalogEntry[];
}

export interface SectionBanner {
    line: number;
    title: LocalizedText;
    url: string | null;
    allUrls: string[];
}

export interface CatalogSection {
    id: string;
    line: number;
    emoji: string | null;
    title: LocalizedText;
    banners: SectionBanner[];
    categories: CatalogCategory[];
}

export interface CatalogStats {
    totalSections: number;
    totalCategories: number;
    totalSubgroups: number;
    totalEntries: number;
    entryKinds: Record<EntryKind, number>;
    totalContentUrls: number;
    uniqueContentUrls: number;
    paidEntries: number;
    freeEntries: number;
    uniqueGithubRepos: number;
    uniqueBlenderExtensions: number;
    licenseCounts: Partial<Record<LicenseCode, number>>;
    platformCounts: Partial<Record<PlatformTag, number>>;
}

export interface CatalogData {
    version: string;
    stats: CatalogStats;
    sections: CatalogSection[];
}
